<script setup>
/**
 * HomeView.vue - 首页视图组件
 *
 * 包含完整的首页所有区块:
 * A. Hero区域(全屏) - 背景图、标题、搜索框、统计栏
 * B. 非遗分类导航 - 8个分类图标卡片
 * C. 热门推荐 - 横向滚动非遗卡片
 * D. 传承人展示 - 代表性传承人横排
 * E. 精品课程 - 课程卡片网格
 * F. 最新资讯 - 新闻卡片
 * G. 社区动态 - 帖子列表
 * H. 平台介绍横幅
 *
 * 所有区块均支持骨架屏loading状态和fade-in入场动画
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import { useRouter } from 'vue-router'
import HeritageCard from '@/components/HeritageCard.vue'
import InheritorCard from '@/components/InheritorCard.vue'
import CourseCard from '@/components/CourseCard.vue'
import NewsCard from '@/components/NewsCard.vue'
import PostCard from '@/components/PostCard.vue'
import SkeletonLoader from '@/components/SkeletonLoader.vue'

// Store和Router
const store = useStore()
const router = useRouter()

// ==================== 搜索 ====================
const searchKeyword = ref('')

/**
 * 处理搜索操作 - 跳转至搜索页面
 */
const handleSearch = () => {
  if (searchKeyword.value.trim()) {
    router.push({ path: '/search', query: { q: searchKeyword.value.trim() } })
  }
}

// ==================== 统计数据 ====================
// 统计数据配置
const stats = [
  { label: '国家级非遗项目', value: 16, suffix: '+', key: 'projects' },
  { label: '非遗传承人', value: 15, suffix: '+', key: 'inheritors' },
  { label: '在线学员', value: 10000, suffix: '+', key: 'students' },
  { label: '注册用户', value: 50000, suffix: '+', key: 'users' }
]

// 动画后的数字 (计数动画用)
const animatedNumbers = ref(stats.map(() => 0))

/**
 * 计数动画效果 - 数字从0滚动到目标值
 * @param {number} index - 统计项索引
 * @param {number} target - 目标数值
 * @param {number} duration - 动画持续时间(ms)
 */
const animateCounter = (index, target, duration = 2000) => {
  const start = performance.now()
  const animate = (currentTime) => {
    const elapsed = currentTime - start
    const progress = Math.min(elapsed / duration, 1)
    // easeOutQuart缓动函数
    const eased = 1 - Math.pow(1 - progress, 4)
    animatedNumbers.value[index] = Math.floor(eased * target)
    if (progress < 1) {
      requestAnimationFrame(animate)
    }
  }
  requestAnimationFrame(animate)
}

// ==================== 非遗分类数据 ====================
const categories = ref([
  { name: '传统技艺', icon: '&#x1F3A8;', count: 28 },
  { name: '传统美术', icon: '&#x1F3AD;', count: 22 },
  { name: '传统音乐', icon: '&#x1F3B5;', count: 18 },
  { name: '传统戏剧', icon: '&#x1F3AC;', count: 15 },
  { name: '传统体育', icon: '&#x26F9;', count: 10 },
  { name: '民间文学', icon: '&#x1F4DA;', count: 20 },
  { name: '传统舞蹈', icon: '&#x1F483;', count: 14 },
  { name: '传统医药', icon: '&#x2695;', count: 12 }
])

const categoriesLoading = ref(false) // 分类数据硬编码，无需加载

/**
 * 点击分类跳转到非遗概览页面并传筛选参数
 * @param {string} categoryName - 分类名称
 */
const navigateToHeritage = (categoryName) => {
  router.push({ path: '/heritage', query: { category: categoryName } })
}

// ==================== 加载状态控制 ====================
const heritageLoading = computed(() => store.state.loading && hotHeritages.value.length === 0)
const inheritorLoading = computed(() => store.state.loading && featuredInheritors.value.length === 0)
const courseLoading = computed(() => store.state.loading && featuredCourses.value.length === 0)
const newsLoading = computed(() => store.state.loading && latestNews.value.length === 0)
const postLoading = computed(() => store.state.loading && latestPosts.value.length === 0)

// ==================== 数据获取 ====================
// 热门推荐数据 (前4个非遗项目)
const hotHeritages = computed(() => store.state.heritages.slice(0, 4))

// 传承人数据 (前3位)
const featuredInheritors = computed(() => store.state.inheritors.slice(0, 3))

// 课程数据 (前4门)
const featuredCourses = computed(() => store.state.courses.slice(0, 4))

// 资讯数据 (前4条)
const latestNews = computed(() => store.state.news.slice(0, 4))

// 社区动态数据 (前4条)
const latestPosts = computed(() => store.state.posts.slice(0, 4))

/**
 * 滚动到内容区域
 */
const scrollToContent = () => {
  const el = document.querySelector('.category-section')
  if (el) {
    el.scrollIntoView({ behavior: 'smooth' })
  }
}

// ==================== 生命周期 ====================
onMounted(async () => {
  // 启动计数动画
  stats.forEach((stat, index) => {
    // 每个数字延迟200ms启动，形成错落效果
    setTimeout(() => {
      animateCounter(index, stat.value)
    }, index * 200)
  })

  // 并行获取所有数据
  try {
    // 获取热门推荐 (非遗项目)
    if (hotHeritages.value.length === 0) {
      await store.dispatch('fetchHeritages', { limit: 4 })
    }
  } catch (err) {
    console.error('获取热门推荐失败:', err)
  }

  try {
    // 获取传承人
    if (featuredInheritors.value.length === 0) {
      await store.dispatch('fetchInheritors', { limit: 3 })
    }
  } catch (err) {
    console.error('获取传承人失败:', err)
  }

  try {
    // 获取课程
    if (featuredCourses.value.length === 0) {
      await store.dispatch('fetchCourses', { limit: 4 })
    }
  } catch (err) {
    console.error('获取课程失败:', err)
  }

  try {
    // 获取资讯
    if (latestNews.value.length === 0) {
      await store.dispatch('fetchNews', { limit: 4 })
    }
  } catch (err) {
    console.error('获取资讯失败:', err)
  }

  try {
    // 获取社区帖子
    if (latestPosts.value.length === 0) {
      await store.dispatch('fetchPosts', { limit: 4 })
    }
  } catch (err) {
    console.error('获取社区动态失败:', err)
  }
})
</script>

